B.aSu=new A.bI("major_03","\u0418\u043c\u043f\u0435\u0440\u0430\u0442\u0440\u0438\u0446\u0430","III","Major Arcana","\u0421\u0442\u0430\u0440\u0448\u0438\u0435 \u0430\u0440\u043a\u0430\u043d\u044b","\u0417\u0435\u043c\u043b\u044f","\u0412\u0435\u043d\u0435\u0440\u0430",B.apg,"\u0414\u0430\u0440\u044b \u0418\u043c\u043f\u0435\u0440\u0430\u0442\u0440\u0438\u0446\u044b \u2013 \u044d\u0442\u043e \u0438\u0437\u043e\u0431\u0438\u043b\u0438\u0435 \u0438 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043c\u0444\u043e\u0440\u0442, \u0447\u0443\u0432\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0438 \u0437\u0430\u0449\u0438\u0449\u0435\u043d\u043d\u043e\u0441\u0442\u044c, \u044d\u043c\u043e\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430. \u042d\u0442\u043e \u0431\u043b\u0430\u0433\u043e\u043f\u0440\u0438\u044f\u0442\u043d\u0430\u044f \u043a\u0430\u0440\u0442\u0430 \u0434\u043b\u044f \u0434\u0435\u0442\u0435\u0439 \u0438 \u0441\u0435\u043c\u0435\u0439, \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0449\u0430\u044f \u0433\u0430\u0440\u043c\u043e\u043d\u0438\u044e \u0432 \u0434\u043e\u043c\u0435. \u0412\u0430\u0448\u0438 \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u044b \u043f\u0440\u043e\u0446\u0432\u0435\u0442\u0430\u044e\u0442, \u0438 \u0432\u044b \u043f\u0440\u0435\u0443\u0441\u043f\u0435\u0432\u0430\u0435\u0442\u0435 \u0432 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u043c \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0438. \u0418\u043c\u043f\u0435\u0440\u0430\u0442\u0440\u0438\u0446\u0430 \u043d\u0430\u0445\u043e\u0434\u0447\u0438\u0432\u0430, \u043f\u043e\u044d\u0442\u043e\u043c\u0443, \u043a\u043e\u0433\u0434\u0430 \u043e\u043d\u0430 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0432 \u0432\u0430\u0448\u0435\u043c \u0447\u0442\u0435\u043d\u0438\u0438, \u0432\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u0431\u044b\u0442\u044c \u0443\u0432\u0435\u0440\u0435\u043d\u044b, \u0447\u0442\u043e \u0432\u0430\u0448\u0438 \u043f\u043e\u0442\u0440\u0435\u0431\u043d\u043e\u0441\u0442\u0438 \u0431\u0443\u0434\u0443\u0442 \u0443\u0434\u043e\u0432\u043b\u0435\u0442\u0432\u043e\u0440\u0435\u043d\u044b.","\u0412 \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u043d\u0443\u0442\u043e\u043c \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0418\u043c\u043f\u0435\u0440\u0430\u0442\u0440\u0438\u0446\u0430 \u0443\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043d\u0430 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u044b\u0435 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0438 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0435 \u0440\u0430\u0437\u0434\u043e\u0440\u044b. \u041e\u043d\u0430 \u0442\u0430\u043a\u0436\u0435 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u043a\u0438\u0439 \u0437\u0430\u0441\u0442\u043e\u0439 \u0432 \u0432\u0430\u0448\u0438\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u0430\u0445 \u0438 \u200b\u200b\u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043d\u0443\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u0432 \u0432\u0430\u0441 \u0438 \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0443 \u0432\u0430\u0441 \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u043c\u043d\u043e\u0433\u043e. \u042d\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u0432\u043b\u0438\u044f\u0442\u044c \u043d\u0430 \u0444\u0435\u0440\u0442\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u2014 \u0431\u0443\u043a\u0432\u0430\u043b\u044c\u043d\u043e \u0441 \u0442\u043e\u0447\u043a\u0438 \u0437\u0440\u0435\u043d\u0438\u044f \u0437\u0430\u0447\u0430\u0442\u0438\u044f \u0440\u0435\u0431\u0435\u043d\u043a\u0430 \u0438\u043b\u0438 \u043e\u0431\u0440\u0430\u0437\u043d\u043e \u0441 \u0442\u043e\u0447\u043a\u0438 \u0437\u0440\u0435\u043d\u0438\u044f \u043f\u043e\u0438\u0441\u043a\u0430 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0438 \u0434\u0443\u0448\u0435\u0432\u043d\u043e\u0433\u043e \u0441\u043f\u043e\u043a\u043e\u0439\u0441\u0442\u0432\u0438\u044f \u0434\u043b\u044f \u0432\u0437\u0440\u0430\u0449\u0438\u0432\u0430\u043d\u0438\u044f \u0438\u0434\u0435\u0438.","\u0418\u043c\u043f\u0435\u0440\u0430\u0442\u0440\u0438\u0446\u0430 \u2014 \u0430\u0440\u0445\u0435\u0442\u0438\u043f \u043c\u0430\u0442\u0435\u0440\u0438, \u0441\u0438\u043c\u0432\u043e\u043b \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u0442\u0432\u0430 \u0438 \u0438\u0437\u043e\u0431\u0438\u043b\u0438\u044f. \u041d\u0430 \u0435\u0435 \u0449\u0438\u0442\u0435 \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d \u0441\u0438\u043c\u0432\u043e\u043b \u0412\u0435\u043d\u0435\u0440\u044b. \u0421\u0438\u0434\u044f\u0449\u0430\u044f \u0432 \u0437\u0435\u043c\u043d\u043e\u043c \u0440\u0430\u044e, \u0433\u0434\u0435 \u0443 \u0435\u0435 \u043d\u043e\u0433 \u0440\u0430\u0441\u0442\u0435\u0442 \u043a\u0443\u043a\u0443\u0440\u0443\u0437\u0430, \u043e\u043d\u0430 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u043e\u043b\u043d\u0435\u0447\u043d\u044b\u0439, \u0437\u0435\u043c\u043d\u043e\u0439 \u0438 \u043f\u043b\u043e\u0434\u043e\u0440\u043e\u0434\u043d\u044b\u0439 \u0430\u0441\u043f\u0435\u043a\u0442 \u0436\u0435\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438.","\u0416\u0438\u0437\u043d\u044c \u0438\u0437\u043e\u0431\u0438\u043b\u0443\u0435\u0442.","assets/tarot/m03.jpg")
